import{_ as e,o as n,c as i,a3 as t}from"./chunks/framework.DACwFHq9.js";const u=JSON.parse('{"title":"索引与检索","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/tools/knowledge-base/indexing.md","filePath":"user-guide/tools/knowledge-base/indexing.md","lastUpdated":1784331351000}'),s={name:"user-guide/tools/knowledge-base/indexing.md"};function l(o,a,r,d,h,p){return n(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="索引与检索" tabindex="-1">索引与检索 <a class="header-anchor" href="#索引与检索" aria-label="Permalink to &quot;索引与检索&quot;">​</a></h1><p>Knowledge 使用两类独立索引：导入后立即可用的 FTS5 关键词索引，以及按资料库和 Embedding 模型隔离的 chunk vector。相邻分块图用于在混合检索中补充上下文。</p><h2 id="索引生命周期" tabindex="-1">索引生命周期 <a class="header-anchor" href="#索引生命周期" aria-label="Permalink to &quot;索引生命周期&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>文件解析</span></span>
<span class="line"><span>  -&gt; document 写入</span></span>
<span class="line"><span>  -&gt; chunk 切分</span></span>
<span class="line"><span>  -&gt; FTS5 更新</span></span>
<span class="line"><span>  -&gt; 相邻分块边更新</span></span>
<span class="line"><span>  -&gt; 可选的 Embedding 批处理</span></span>
<span class="line"><span>  -&gt; 当前模型覆盖率更新</span></span></code></pre></div><p>原文档是来源真源，chunk、FTS、vector 和 graph edge 都是可重建资产。</p><h2 id="关键词索引" tabindex="-1">关键词索引 <a class="header-anchor" href="#关键词索引" aria-label="Permalink to &quot;关键词索引&quot;">​</a></h2><p>关键词索引不依赖外部模型。文档成功导入后即可使用 <code>keyword</code>，<code>auto</code> 在没有可用向量时也会退化到 BM25。</p><h2 id="语义索引" tabindex="-1">语义索引 <a class="header-anchor" href="#语义索引" aria-label="Permalink to &quot;语义索引&quot;">​</a></h2><p>点击“语义索引”选择 Embedding 模型。系统按批次请求向量并写入当前资料库的 <code>.kdb</code>。</p><p>状态区显示：</p><ul><li>当前模型</li><li>向量维度</li><li>分块总数</li><li>已向量化分块数</li><li>待处理分块数</li></ul><p>覆盖率来自数据库实时统计，不依赖前端缓存。</p><h2 id="切换模型" tabindex="-1">切换模型 <a class="header-anchor" href="#切换模型" aria-label="Permalink to &quot;切换模型&quot;">​</a></h2><p>不同模型的向量不能混在同一检索空间中。系统使用“渠道配置 + 模型 ID”共同标识模型，避免不同渠道的同名模型混用。切换模型后，新模型成为当前语义检索基准，覆盖率按新模型重新计算。旧模型记录不会参与当前 semantic/hybrid 检索。</p><h2 id="检索策略" tabindex="-1">检索策略 <a class="header-anchor" href="#检索策略" aria-label="Permalink to &quot;检索策略&quot;">​</a></h2><h3 id="自动" tabindex="-1">自动 <a class="header-anchor" href="#自动" aria-label="Permalink to &quot;自动&quot;">​</a></h3><p>单库有当前 Embedding 模型时，前端先为查询生成向量并使用 hybrid；没有模型或无法生成向量时退化为 BM25。</p><h3 id="关键词" tabindex="-1">关键词 <a class="header-anchor" href="#关键词" aria-label="Permalink to &quot;关键词&quot;">​</a></h3><p>使用 FTS5 BM25，适合专有名词、文件内容和精确短语。</p><h3 id="语义" tabindex="-1">语义 <a class="header-anchor" href="#语义" aria-label="Permalink to &quot;语义&quot;">​</a></h3><p>使用 cosine similarity 搜索当前模型的 chunk vector。只有已覆盖分块参与候选。</p><h3 id="混合" tabindex="-1">混合 <a class="header-anchor" href="#混合" aria-label="Permalink to &quot;混合&quot;">​</a></h3><p>融合 BM25 与 vector 候选，并可通过相邻 chunk graph 补充上下文。结果 signals 会说明每个候选使用了哪些信号。</p><h2 id="分数说明" tabindex="-1">分数说明 <a class="header-anchor" href="#分数说明" aria-label="Permalink to &quot;分数说明&quot;">​</a></h2><p>BM25、cosine similarity 和图扩展分数不是同一种量纲。界面显示原始相关度和命中信号，不把它们转换为看似统一的百分比。</p><h2 id="失败恢复" tabindex="-1">失败恢复 <a class="header-anchor" href="#失败恢复" aria-label="Permalink to &quot;失败恢复&quot;">​</a></h2><p>向量化按批次提交。请求失败时，已提交批次保留；重新执行构建会覆盖写入同一模型的 chunk vector，并继续补齐覆盖。</p><p>重建分块会使旧 chunk ID 失效，因此重建会清除当前语义索引配置，防止误用旧向量。</p>`,28)])])}const b=e(s,[["render",l]]);export{u as __pageData,b as default};
